package licensesrv
import("encoding/json";"reflect";"strings";"testing";"time")
func TestPanelV41AuthWrongCodeLedger(t *testing.T){s,tok,now:=v4Fixture(t);key:="local-license-sentinel";l:=&License{Key:key,Email:"owner@example.test",OrderID:42,Plan:Plan{Kind:"sub",Credits:10},Credits:10,Reserved:2,IssuedAt:now,ExpiresAt:now.Add(time.Hour)};s.st.Licenses[key]=l;s.st.LicenseOwners[key]="v4-account";s.st.Orders["42"]=[]string{key};s.st.Reservations["open-local"]=&Reservation{Key:key,Amount:2,CreatedAt:now,Expires:now.Add(time.Hour)};s.st.Settlements["prior-local"]=Settlement{Key:key,Commit:true,Amount:1,CreatedAt:now,SettledAt:now};var raw map[string]json.RawMessage;v,_:=json.Marshal(s.st);json.Unmarshal(v,&raw);raw["refunds"]=json.RawMessage(`{"refund-local":{"orderId":42,"lines":{"1":1}}}`);v,_=json.Marshal(raw);if e:=json.Unmarshal(v,&s.st);e!=nil{t.Fatal(e)}
 snap:=func()string{v,_:=json.Marshal(s.st);return string(v)};before:=snap();for _,bad:=range []string{"","unknown",tok+"x",key}{if _,e:=s.ExportPrivacy(bad,now,nil);e==nil{t.Fatal("unauthorized export")};if e:=s.RequestErase(bad,now);e==nil{t.Fatal("unauthorized request")};if _,e:=s.ConfirmErase(bad,"bad-code","fixture-password",now);e==nil{t.Fatal("unauthorized confirm")}};if snap()!=before{t.Fatal("bad auth mutated ledger")}
 if e:=s.RequestErase(tok,now);e!=nil{t.Fatal(e)};before=snap();if _,e:=s.ConfirmErase(tok,"bad-code","fixture-password",now);e==nil{t.Fatal("bad code accepted")};if snap()!=before{t.Fatal("bad code changed ledger")};var code string;for _,m:=range s.st.Outbox{if strings.Contains(m.Body,"silme onay kodu"){for _,v:=range strings.Fields(m.Body){if len(v)==32{code=v}}}};if code==""{t.Fatal("fixture challenge missing")};orders,_:=json.Marshal(s.st.Orders);refunds,_:=json.Marshal(s.st.Refunds);prior:=s.st.Settlements["prior-local"]
 result,e:=s.ConfirmErase(tok,code,"fixture-password",now);if e!=nil{t.Fatal(e)};o,_:=json.Marshal(s.st.Orders);r,_:=json.Marshal(s.st.Refunds);if string(o)!=string(orders)||string(r)!=string(refunds)||!reflect.DeepEqual(prior,s.st.Settlements["prior-local"]){t.Fatal("prior orders/refunds/settlements lost")};lic:=s.st.Licenses[key];if lic==nil||!lic.Revoked||lic.Reserved!=0||lic.Credits!=0||strings.Contains(lic.Email,"owner")||!strings.Contains(result.PseudonymEmail,"@anon.invalid"){t.Fatal("ledger retained/anonymized contract")};if len(s.st.Reservations)!=0||len(s.st.LicenseOwners)!=0{t.Fatal("active reservations/ownership retained")};t.Log("bad auth/code no mutation; valid erase preserves prior ledger, revokes license and releases hold without refund")}
